sys_variable_value.value:
(function execute(inputs, outputs) {

    var sourceRecord = inputs.trigger_record;
    var targetTableReference = inputs.target_table_reference;

    if (!sourceRecord || !sourceRecord.sys_id) {
        outputs.success = false;
        outputs.errorMessage = "Source Record inválido.";
        return;
    }

    if (!targetTableReference || !targetTableReference.sys_id) {
        outputs.success = false;
        outputs.errorMessage = "Referência da tabela de destino inválida ou sys_id ausente.";
        return;
    }

    var mappings = new x_sded9_portal_t_0.MRVSUpsertMappingsUtil().getMappings();
    if (!mappings) {
        outputs.success = false;
        outputs.errorMessage = "Configuração de mapeamento ausente ou inválida do Script Include.";
        return;
    }

    var targetTableName = targetTableReference.getDisplayValue();

    if (!targetTableName) {
        outputs.success = false;
        outputs.errorMessage = "Nome da tabela de destino não pôde ser resolvido a partir da referência fornecida.";
        return;
    }

    var targetTableMapping = mappings[targetTableName];
    if (!targetTableMapping) {
        outputs.success = false;
        outputs.errorMessage = "Mapeamento para a tabela de destino '" + targetTableName + "' não configurado no Script Include.";
        return;
    }

    var mrvsData = {};
    var sourceRecordSysId = sourceRecord.sys_id;

    var grMRVS = new GlideRecord('sc_multi_row_Youtube');
    grMRVS.addQuery('parent_id', sourceRecordSysId);
    grMRVS.query();

    while (grMRVS.next()) {
        var rowIndexSysId = grMRVS.row_index.toString();
        var variableSysId = grMRVS.item_option_new.sys_id.toString();
        var value = grMRVS.value.toString();

        if (!mrvsData[rowIndexSysId]) {
            mrvsData[rowIndexSysId] = {};
        }
        mrvsData[rowIndexSysId][variableSysId] = value;
    }

    var successfulUpserts = [];
    var failedUpserts = [];
    var rowIndexes = Object.keys(mrvsData);

    if (rowIndexes.length === 0) {
        outputs.success = true;
        outputs.upsertedRecordSysId = '';
        outputs.operationType = "No MRVS Data";
        return;
    }

    rowIndexes.forEach(function(currentMRVSRowSysId) {
        var currentMRVSRowData = mrvsData[currentMRVSRowSysId];
        var grTarget = new GlideRecord(targetTableName);
        var isUpdate = false;
        var currentUpsertResult = {
            rowIndexSysId: currentMRVSRowSysId,
            success: false,
            message: '',
            sysId: '',
            operationType: ''
        };

        if (targetTableMapping.mrvs_key_mappings && targetTableMapping.mrvs_key_mappings.length > 0) {
            for (var mrvsKeyMap of targetTableMapping.mrvs_key_mappings) {
                var mrvsVariableSysId = mrvsKeyMap.mrvs_variable_sys_id;
                var targetKeyField = mrvsKeyMap.target_field_name;

                var mrvsKeyValue = currentMRVSRowData[mrvsVariableSysId];

                if (typeof mrvsKeyValue !== 'undefined' && mrvsKeyValue !== null && mrvsKeyValue !== '') {
                    grTarget.addQuery(targetKeyField, mrvsKeyValue);
                }
            }
        } else {
            currentUpsertResult.message = "Mapeamento de chaves MRVS ausente ou vazio.";
            failedUpserts.push(currentUpsertResult);
            return;
        }

        grTarget.query();

        if (grTarget.next()) {
            isUpdate = true;
        } else {
            grTarget.initialize();
        }

        if (targetTableMapping.mrvs_field_mappings && targetTableMapping.mrvs_field_mappings.length > 0) {
            targetTableMapping.mrvs_field_mappings.forEach(function(mrvsMap) {
                var mrvsVariableSysId = mrvsMap.mrvs_variable_sys_id;
                var targetField = mrvsMap.target_field_name;

                if (typeof currentMRVSRowData[mrvsVariableSysId] !== 'undefined') {
                    grTarget.setValue(targetField, currentMRVSRowData[mrvsVariableSysId]);
                }
            });
        }

        var upsertedSysId = '';
        try {
            if (isUpdate) {
                upsertedSysId = grTarget.update();
                currentUpsertResult.message = "Atualizado com sucesso.";
                currentUpsertResult.operationType = "Updated";
            } else {
                upsertedSysId = grTarget.insert();
                currentUpsertResult.message = "Inserido com sucesso.";
                currentUpsertResult.operationType = "Inserted";
            }
            currentUpsertResult.success = true;
            currentUpsertResult.sysId = upsertedSysId;
            successfulUpserts.push(currentUpsertResult);

        } catch (e) {
            currentUpsertResult.message = "Erro ao salvar: " + e.getMessage();
            currentUpsertResult.operationType = isUpdate ? "Update Failed" : "Insert Failed";
            failedUpserts.push(currentUpsertResult);
        }
    });

    outputs.success = failedUpserts.length === 0;
    outputs.upsertresults = successfulUpserts.concat(failedUpserts); // <--- ALTERADO AQUI
    if (outputs.success) {
        outputs.errorMessage = "";
    } else {
        outputs.errorMessage = "Falhas ocorreram durante o processamento de " + failedUpserts.length + " linhas MRVS.";
    }

})(inputs, outputs);

